llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Absolute oral bioavailability of 17-beclomethasone monopropionate, the closest steroid analogue (same scaffold, chlorine, and 17-hydroxyacetyl; only 17-propionate vs 17-OH), was 41% (90% CI 31–54%) versus IV in healthy subjects, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "A second human study reported 17-BMP systemic bioavailability of 21% when summing BDP and metabolite AUCs, still meeting the ≥20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Chlormadinone acetate, a chlorinated steroid, had approximately 100% oral bioavailability in humans, supporting high oral absorption for chlorinated steroid scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Cyproterone acetate, another chlorinated steroid, showed almost complete absolute oral bioavailability (88% of dose) in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Nomegestrol acetate, a steroid progestin, had 63.4% absolute oral bioavailability in healthy women, supporting high F for steroid-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Danazol in the fasted state had low absolute bioavailability (11 ± 5.2%) due to poor solubility; this is a solubility-limited counterexample, but the query has much lower logP and favorable solubility, and fed-state danazol reached 44–67%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest and highest-transfer evidence, 17-beclomethasone monopropionate, shows human absolute oral bioavailability of 41% (31–54%), well above the 20% threshold. Multiple chlorinated/steroid analogues also show high oral F. The only low-F evidence (fasted danazol) is solubility-limited and less applicable to this more polar, soluble steroid. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for beclomethasone itself; the closest evidence is 17-BMP, differing by a 17-propionate ester.",
    "First-pass metabolism or transporter effects specific to the free 17-hydroxy form are not directly measured.",
    "Danazol data illustrate formulation/food dependence, but the query's solubility is favorable; no fed/fasted comparison for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

